const cache={};
function img(src){if(!cache[src])cache[src]=new Promise(ok=>{const i=new Image();i.onload=()=>ok(i);i.onerror=()=>ok(null);i.src=src});return cache[src]}
const svgUrl=(vb,w,h,inner)=>URL.createObjectURL(new Blob([`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb.join(' ')}" width="${Math.round(w)}" height="${Math.round(h)}" preserveAspectRatio="xMidYMid meet" font-family="Helvetica, Arial, sans-serif">${inner}</svg>`],{type:'image/svg+xml'}));
