 x.save();x.beginPath();x.arc(cx,cy,d/2,0,7);x.clip();
 if(im)x.drawImage(im,cx-d/2,cy-d/2,d,d);else{x.fillStyle='#1C3970';x.fillRect(cx-d/2,cy-d/2,d,d);x.fillStyle='#fff';x.font=`700 ${d*.36}px ${FC}`;x.textAlign='center';x.textBaseline='middle';x.fillText(String(n).slice(0,2),cx,cy)}
